package day21;

import java.util.HashMap;

public class RobotReturnToOrigin_657 {
    static void main() {
        String s="";
        System.out.println(returnToOrigin(s));
    }
    public static boolean returnToOrigin(String m){
        int u=0,d=0,l=0,r=0;
        for(char c:m.toCharArray()){
            if(c=='U'){
                u++;
            }else if(c=='D'){
                d++;
            }else if(c=='L'){
                l++;
            }else if(c=='R'){
                r++;
            }
        }
        return u==d && l==r;
    }
}
